import html
import json
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = json.loads((ROOT / "research" / "dataset.json").read_text(encoding="utf-8"))
ITEMS = DATA["items"]
BASE = [x for x in ITEMS if not x.get("secop")]
SECOP = [x for x in ITEMS if x.get("secop")]
STATUS = {"abierta":"Abierta", "activa":"Activa / permanente", "cerrada":"Cerrada", "historico":"Antecedente / vigilar", "proxima":"Próxima estimada", "pausada":"Pausada", "no_elegible":"No elegible directamente", "secop":"SECOP · confirmar plazo"}
SITE = "https://alarconmd.github.io/economia-plateada-colombia/"
PDF = "Informe_Economia_Plateada_Colombia_19NOV2026.pdf"


def e(value):
    return html.escape(str(value), quote=True)


def links(item):
    return "".join(f"<li><a href='{e(s['url'])}'>{e(s['titulo'])}</a><br><span class='tiny muted'>{e(s['url'])}</span></li>" for s in item["fuentes"])


def ficha(item, compact=False):
    badges = f"<span class='badge {item['estado']}'>{STATUS[item['estado']]}</span><span class='badge'>{e(item['tipo'])}</span><span class='badge'>Prioridad {e(item['prioridad'])}</span>"
    body = f"""<article class='ficha {'secop' if item.get('secop') else ''}' id='{e(item['id'])}'>
    <div class='badges'>{badges}</div><h3>{e(item['nombre'])}</h3>
    <p><strong>{e(item['entidad'])}</strong><br><span class='muted'>{e(item['territorio'])}</span></p>
    <div class='meta-grid'><div><span class='label'>Recursos / modalidad</span>{e(item['monto'])}</div><div><span class='label'>Fecha / estado</span>{e(item['cierre'])}</div></div>
    <h4>Objetivo</h4><p>{e(item['objetivo'])}</p><h4>Encaje con economía plateada</h4><p>{e(item['encaje'])}</p>
    <div class='grid-2'><div><h4>Quién puede participar</h4><ul>{''.join('<li>'+e(x)+'</li>' for x in item['postulantes'])}</ul></div>
    <div><h4>Temas</h4><p>{e(' · '.join(item['temas']))}</p><h4>Canal</h4><p>{e(item['canal'])}</p></div></div>
    <h4>Requisitos y condiciones</h4><ul class='checklist'>{''.join('<li>'+e(x)+'</li>' for x in item['requisitos'])}</ul>
    <h4>Presencia física y ejecución</h4><p>{e(item['presencia'])}</p>
    <div class='callout'><strong>Siguiente acción:</strong> {e(item['accion'])}</div>"""
    if item.get("nota"):
        body += f"<p class='small muted'><strong>Nota de verificación:</strong> {e(item['nota'])}</p>"
    body += f"<div class='sources'><strong>Fuentes primarias</strong><ul>{links(item)}</ul></div></article>"
    return body


def table_rows(items, secop=False):
    rows=[]
    for x in items:
        if secop:
            rows.append(f"<tr><td><a href='{e(x['fuentes'][0]['url'])}'>{e(x['referencia'])}</a><br><span class='tiny'>{e(x['id_proceso'])}</span></td><td>{e(x['entidad'])}<br><span class='tiny'>{e(x['territorio'])}</span></td><td>{e(x['nombre'])}</td><td class='num'>{e(x['monto'].replace(' COP',''))}</td><td>{e(x['actualizacion'][:10])}</td></tr>")
        else:
            rows.append(f"<tr><td><a href='#{e(x['id'])}'>{e(x['nombre'])}</a></td><td>{e(x['entidad'])}</td><td><span class='badge {x['estado']}'>{STATUS[x['estado']]}</span></td><td>{e(x['monto'])}</td><td>{e(x['cierre'])}</td></tr>")
    return "".join(rows)


def chapter_intro(number, title, subtitle):
    return f"<div class='chapter-title'><div class='eyebrow'>Capítulo {number}</div><h1>{e(title)}</h1><p class='lead'>{e(subtitle)}</p></div>"


def make_document():
    counts=Counter(x['estado'] for x in ITEMS)
    local_secop=[x for x in SECOP if x['cap']==1]
    chapters=[]
    chapters.append(f"""<section class='cover'><div><div class='kicker'>Investigación aplicada · Colombia</div><h1>Financiación y desarrollo de proyectos de economía plateada</h1><p class='lead'>Bogotá–Cundinamarca, cobertura nacional, SECOP II, regalías, ministerios, ONG y cooperación internacional</p></div><div><div class='grid-3'><div class='metric'><strong>{len(ITEMS)}</strong>registros trazables</div><div class='metric'><strong>{len(BASE)}</strong>iniciativas y fondos</div><div class='metric'><strong>{len(SECOP)}</strong>candidatos SECOP II</div></div></div><div class='meta'><strong>Corte de fuentes:</strong> 19 de noviembre de 2026<br><strong>Corte SECOP:</strong> 19 de noviembre de 2026, 09:32, hora de Colombia<br><strong>Versión:</strong> 1.0 · Documento con enlaces clicables<br><br><a href='{SITE}'>Explorador interactivo: {SITE}</a></div></section>""")
    chapters.append(f"""<section><div class='eyebrow'>Guía de lectura</div><h1>Contenido y decisiones que responde</h1><div class='toc'><a href='#resumen'>Resumen ejecutivo y oportunidades accionables</a><a href='#cap1'>Capítulo 1 · Bogotá, Cundinamarca y CCB</a><a href='#cap2'>Capítulo 2 · Resto del país, regalías, ministerios y SECOP II</a><a href='#cap3'>Capítulo 3 · ONG y fondos internacionales</a><a href='#ruta'>Ruta de implementación, elegibilidad y presencia física</a><a href='#metodo'>Metodología, limitaciones y fuentes</a></div><h2>Preguntas de decisión</h2><div class='grid-2'><div class='callout'><strong>¿Dónde hay financiación?</strong><br>Distingue subvención, capital semilla, contratación, asistencia, inversión pública y crowdfunding.</div><div class='callout'><strong>¿Puedo participar?</strong><br>Cada ficha identifica postulantes, requisitos, territorio, presencia física y canal.</div><div class='callout warn'><strong>¿Sigue abierta?</strong><br>“Cerrada” e “histórico” no son oportunidades actuales. “SECOP · confirmar plazo” exige abrir el aviso hoy.</div><div class='callout'><strong>¿Qué hacer después?</strong><br>Cada registro incluye una acción concreta y enlaces a la fuente primaria.</div></div><p class='small muted'>El informe no certifica elegibilidad jurídica, disponibilidad presupuestal ni adjudicación. Las fechas, documentos y montos deben reconfirmarse con la entidad antes de comprometer recursos.</p></section>""")
    immediate=[x for x in BASE if x['estado']=='abierta']
    chapters.append(f"""<section id='resumen'><div class='eyebrow'>Resumen ejecutivo</div><h1>Qué está realmente disponible</h1><p class='lead'>La oportunidad más sólida no es un único “fondo plateado”, sino una combinación de desarrollo empresarial, contratación pública, inversión territorial y cooperación según el tipo de proyecto.</p><div class='grid-3'><div class='metric'><strong>{len(immediate)}</strong>registros no-SECOP abiertos</div><div class='metric'><strong>{len(SECOP)}</strong>procesos por confirmar</div><div class='metric'><strong>{counts['cerrada']+counts['historico']}</strong>cerrados o antecedentes</div></div><h2>Seis conclusiones</h2><ol><li><strong>Bogotá–Región sí tiene ecosistema especializado.</strong> El programa y clúster CCB son puertas inmediatas para empresas; ofrecen acompañamiento gratuito y articulación, no desembolso garantizado.</li><li><strong>Cundinamarca tiene una asignación concreta.</strong> Los $9.500 millones de la Estampilla 2026 se distribuyen institucionalmente a Centros Día/Vida y larga estancia; la ruta es municipal y de contratación de operadores.</li><li><strong>SECOP II sí contiene ofertas aplicables.</strong> Se conservaron {len(SECOP)} candidatos actualizados en noviembre: infraestructura, alimentación, operación de centros, geriatría, rehabilitación oral, logística y política pública. El dataset no expone cierre; reconfirmar cada aviso.</li><li><strong>Las regalías exigen un actor habilitado.</strong> SGR, Anexo 15, OCAD Paz y CTeI 54–56 son inversión pública, no grants privados. Las ediciones específicas revisadas están cerradas.</li><li><strong>Hay tres opciones internacionales accionables con condiciones estrictas:</strong> D-Prize (hasta USD 20.000, prórroga 6 de diciembre), DRK (hasta USD 300.000 en tres años) y Pollination Project (cierre anual 30 de noviembre). GlobalGiving es crowdfunding.</li><li><strong>El filtro evita desperdicio:</strong> IAF está pausada; Wellcome Discovery no admite sede administradora colombiana; GIF prioriza África/Asia; CAF LIF 2026 cerró.</li></ol><h2>Acción inmediata</h2><table><thead><tr><th>Oportunidad</th><th>Entidad</th><th>Estado</th><th>Recursos</th><th>Plazo / verificación</th></tr></thead><tbody>{table_rows(immediate)}</tbody></table><div class='callout warn'><strong>SECOP II:</strong> use el filtro “SECOP · confirmar plazo”. Abra el aviso, descargue pliegos y verifique recepción antes de preparar oferta. “Abierto” en el dataset no garantiza que el plazo siga habilitado.</div></section>""")
    chapters.append("""<section><div class='eyebrow'>Método de interpretación</div><h1>Economía plateada y tipos de instrumento</h1><p>Alcance amplio: productos y servicios para personas de 50/60 años o más según cada fuente; envejecimiento activo y saludable; cuidado y dependencia; empleo y emprendimiento senior; inclusión financiera/digital; accesibilidad, vivienda, movilidad, cultura, recreación y participación.</p><table><thead><tr><th>Instrumento</th><th>Qué recibe el participante</th><th>Riesgo de interpretación</th></tr></thead><tbody><tr><td>Subvención / capital semilla</td><td>Recursos para ejecutar una propuesta</td><td>Exige elegibilidad, indicadores y reportes.</td><tr><td>Contratación pública / convenio</td><td>Pago por un objeto definido por la entidad</td><td>No financia libremente una iniciativa propia.</td><tr><td>Asignación pública / SGR</td><td>Inversión aprobada a entidad habilitada</td><td>ONG/empresa suele participar como aliada o contratista.</td><tr><td>Aceleración / asistencia</td><td>Capacidades, redes o diagnóstico</td><td>No equivale a capital garantizado.</td><tr><td>Transferencia a personas</td><td>Apoyo individual, como Colombia Mayor</td><td>No es ingreso institucional.</td><tr><td>Crowdfunding</td><td>Donaciones captadas</td><td>Depende de selección, donantes, tarifas y campaña.</td></tbody></table><h2>Estados usados</h2><p><strong>Abierta:</strong> canal actual o recepción continua. <strong>Activa:</strong> programa vigente sin convocatoria necesariamente abierta. <strong>Próxima:</strong> fecha futura estimada sin bases finales. <strong>Histórico:</strong> antecedente o ruta sin ventana verificada. <strong>Cerrada:</strong> plazo superado/adjudicada. <strong>Pausada/no elegible:</strong> no recomendable. <strong>SECOP:</strong> candidato que requiere confirmar cierre y pliegos.</p></section>""")
    cap1=[x for x in BASE if x['cap']==1]
    chapters.append(f"""<section class='chapter' id='cap1'>{chapter_intro(1,'Bogotá, Gobernación de Cundinamarca y CCB','Iniciativas locales, financiación, operación y presencia física en Bogotá–Región')}<h2>Lectura estratégica de la región</h2><p>Bogotá combina <strong>desarrollo empresarial</strong> (CCB), <strong>operación social</strong> (SDIS), <strong>cuidado</strong> (Sistema Distrital), <strong>cultura</strong> (Idartes/SCRD) y <strong>participación</strong> (IDPAC). Cundinamarca agrega una fuente presupuestal específica mediante la Estampilla, descentralizada a 116 municipios.</p><div class='grid-2'><div class='callout'><strong>Empresa/startup:</strong> empezar por CCB; para contratación, vigilar SECOP. Usar CAF/DRK solo con tracción y escala.</div><div class='callout'><strong>ESAL/organización de mayores:</strong> preparar personería, experiencia y plan local; observar SDIS, PDAC, Chikaná y procesos municipales.</div></div><h2>Mapa de oportunidades locales</h2><table><thead><tr><th>Iniciativa</th><th>Entidad</th><th>Estado</th><th>Recursos</th><th>Plazo</th></tr></thead><tbody>{table_rows(cap1)}</tbody></table><h2>Fichas detalladas</h2>{''.join(ficha(x) for x in cap1)}<h2>SECOP II en Bogotá y Cundinamarca</h2><p>Se identificaron <strong>{len(local_secop)}</strong> candidatos territoriales en la selección de noviembre. La ubicación corresponde a la entidad reportada; el objeto puede ejecutarse en otro municipio. Confirmar siempre el lugar en el expediente.</p><table><thead><tr><th>Proceso</th><th>Entidad / territorio</th><th>Objeto</th><th>Presupuesto</th><th>Actualización</th></tr></thead><tbody>{table_rows(local_secop,True)}</tbody></table></section>""")
    cap2=[x for x in BASE if x['cap']==2]
    chapters.append(f"""<section class='chapter' id='cap2'>{chapter_intro(2,'Resto del país: programas, ministerios, regalías y SECOP II','Rutas nacionales y territoriales para estructurar, financiar o ejecutar proyectos')}<h2>Arquitectura nacional de oportunidades</h2><p>Para el resto del país se identifican cinco rutas complementarias: <strong>(1)</strong> inversión pública SGR y OCAD; <strong>(2)</strong> ciencia, tecnología e innovación; <strong>(3)</strong> capital semilla SENA; <strong>(4)</strong> cultura, participación y cooperación técnica; y <strong>(5)</strong> contratación pública local. Las transferencias como Colombia Mayor se describen por su relevancia social, pero no como financiación institucional.</p><div class='callout warn'><strong>No hay una ventana nacional general abierta verificada en MinCiencias, Fondo Emprender o MinCultura al corte.</strong> Las convocatorias recientes tienen valor como mapa de preparación. La Concertación Cultural se proyecta para enero–febrero de 2027, aún sin reglas finales.</div><h2>Regalías: ruta obligatoria</h2><ol><li>Definir necesidad y resultado de inversión pública, no solo actividad asistencial.</li><li>Identificar fuente SGR, finalidad, entidad beneficiaria y OCAD territorial/temático.</li><li>Formalizar patrocinio de la entidad habilitada y revisar Anexo 15 para salud/protección social.</li><li>Preparar MGA, indicadores, costos, sostenibilidad operativa, BPIN y documentos en SUIFP/PIIP.</li><li>Superar viabilidad, requisitos, priorización y aprobación; después contratar, ejecutar y reportar.</li></ol><p>En OCAD Paz, el universo habilitado y la concordancia PATR/ART son indispensables. En CTeI 54 y 55, la escala territorial y la alianza son criterios de diseño: dos departamentos de una región o dos regiones, respectivamente.</p><h2>Mapa nacional</h2><table><thead><tr><th>Iniciativa</th><th>Entidad</th><th>Estado</th><th>Recursos</th><th>Plazo</th></tr></thead><tbody>{table_rows(cap2)}</tbody></table><h2>Fichas nacionales y de regalías</h2>{''.join(ficha(x) for x in cap2)}</section>""")
    chapters.append(f"""<section class='chapter' id='secop'><div class='chapter-title'><div class='eyebrow'>Capítulo 2 · Sección especial</div><h1>SECOP II: 27 candidatos para revisión inmediata</h1><p class='lead'>Contratos y convenios relacionados con personas mayores, cuidado, geriatría, accesibilidad y participación.</p></div><h2>Cómo se obtuvo la selección</h2><p>Fuente: Colombia Compra Eficiente, dataset <strong>SECOP II – Procesos de Contratación, p6dx-8zbt</strong>, actualización diaria. Consulta por términos en el nombre del procedimiento: economía plateada, persona(s) mayor(es), adulto(s) mayor(es), envejecimiento, vejez, geriatría, gerontología, longevidad, cuidadores, Centro Vida/Día, pensionados y dependencia.</p><p>La búsqueda inicial produjo 1.387 registros brutos. Se exigió fase de presentación de ofertas, no contratación directa, relación explícita y actualización desde el 1 de noviembre de 2026. Quedaron 27 candidatos. Se excluyeron de esta selección fases de observaciones y registros antiguos que seguían marcados como abiertos. No se suman los presupuestos porque hay modalidades y objetos heterogéneos.</p><div class='callout danger'><strong>Advertencia crítica:</strong> el dataset no contiene una columna de fecha/hora de cierre. “Publicado”, “abierto” y “no adjudicado” no prueba que la recepción siga habilitada. Cada fila es un candidato para verificar, no una garantía de oportunidad abierta.</div><h2>Requisitos transversales para ofertar</h2><div class='grid-2'><ul><li>Cuenta de proveedor en SECOP II y RUP cuando aplique.</li><li>Leer aviso, estudios previos, pliego, anexos, adendas y respuestas.</li><li>Verificar experiencia, capacidad financiera/técnica, equipo, garantías y consorcios.</li><li>Confirmar objeto, cantidades, lugar, plazo, visitas y obligaciones sociales.</li></ul><ul><li>Preparar oferta técnica/económica y documentos en formatos exigidos.</li><li>Presentar electrónicamente antes del cierre real.</li><li>Evaluar habilitación de ESAL para convenios y régimen especial.</li><li>Presupuestar supervisión, seguros, reportes, accesibilidad y protección de datos.</li></ul></div><h2>Tabla nacional de candidatos</h2><table><thead><tr><th>Proceso</th><th>Entidad / territorio</th><th>Objeto</th><th>Presupuesto</th><th>Actualización</th></tr></thead><tbody>{table_rows(SECOP,True)}</tbody></table><h2>Fichas de los 27 procesos</h2>{''.join(ficha(x,True) for x in SECOP)}</section>""")
    cap3=[x for x in BASE if x['cap']==3]
    chapters.append(f"""<section class='chapter' id='cap3'>{chapter_intro(3,'ONG, cooperación y fondos internacionales','Ventanas abiertas, financiación histórica, proyectos en implementación y restricciones para Colombia')}<h2>Prioridad por tipo de proyecto</h2><table><thead><tr><th>Proyecto</th><th>Fuente más adecuada</th><th>Condición crítica</th></tr></thead><tbody><tr><td>Distribución de gafas u otra solución probada contra pobreza</td><td>D-Prize · hasta USD 20.000</td><td>Nueva organización, evidencia de intervención y piloto; prórroga hasta 6 dic 2026.</td><tr><td>Empresa social plateada con tracción y escala</td><td>DRK · hasta USD 300.000 / 3 años</td><td>No idea/pre-piloto; resultados, liderazgo, escala y gobierno.</td><tr><td>Acción comunitaria voluntaria temprana</td><td>Pollination Project</td><td>Presupuestos pequeños, voluntariado, solicitud en inglés y referee; 30 nov 2026.</td><tr><td>Recaudación internacional de ONG</td><td>GlobalGiving</td><td>Invitación, workbook y due diligence; no grant garantizado.</td><tr><td>Startup financiera/digital 50+</td><td>CAF LIF · próxima edición</td><td>2026 cerró; solución activa, tracción y operación en país CAF.</td><tr><td>Ecosistema regional de startups</td><td>BID Silver Ventures</td><td>Proyecto en implementación; esperar canal/convocatoria específica.</td><tr><td>Participación democrática de mayores</td><td>UNDEF · próxima ventana</td><td>No servicios asistenciales; propuesta en inglés/francés.</td><tr><td>Violencia contra mujeres mayores</td><td>ONU Mujeres · próxima estimada 2027</td><td>OSC especializada; no economía plateada general.</td></tbody></table><div class='callout danger'><strong>No recomendados para solicitud directa ahora:</strong> IAF (pausa), Wellcome Discovery (geografía de sede no incluye Colombia) y Global Innovation Fund (prioridad África/Asia).</div><h2>Mapa internacional completo</h2><table><thead><tr><th>Iniciativa</th><th>Entidad</th><th>Estado</th><th>Recursos</th><th>Plazo</th></tr></thead><tbody>{table_rows(cap3)}</tbody></table><h2>Fichas detalladas</h2>{''.join(ficha(x) for x in cap3)}</section>""")
    chapters.append("""<section class='chapter' id='ruta'><div class='chapter-title'><div class='eyebrow'>Aplicación práctica</div><h1>Ruta de preparación y participación</h1><p class='lead'>Una secuencia para convertir la investigación en un pipeline de proyectos sin sobrestimar elegibilidad ni recursos.</p></div><h2>1. Elegir arquetipo antes de buscar fondo</h2><table><thead><tr><th>Arquetipo</th><th>Resultado verificable</th><th>Rutas preferentes</th></tr></thead><tbody><tr><td>Inclusión financiera/digital 50+</td><td>Usuarios activos, transacciones, alfabetización y protección</td><td>CCB, DRK, futura CAF, SECOP tecnológico</td><tr><td>Centro Día/Vida o cuidado de dependencia</td><td>Cupos, horas de cuidado, autonomía, respiro y calidad</td><td>Estampilla municipal, SDIS, SGR, SECOP</td><tr><td>Tecnología de asistencia / salud</td><td>Validación, adopción, resultados de salud y escala</td><td>MinCiencias, BID, DRK, SECOP salud</td><tr><td>Cultura y envejecimiento activo</td><td>Participación, creación, circulación y bienestar</td><td>Idartes, Más Cultura Local, MinCultura, Pollination</td><tr><td>Participación y derechos</td><td>Incidencia, liderazgo y reducción de discriminación</td><td>Chikaná, UNDEF, ONU Mujeres si violencia</td><tr><td>Distribución de ayudas visuales</td><td>Personas evaluadas, gafas entregadas, uso y seguimiento</td><td>D-Prize y donaciones complementarias</td></tbody></table><h2>2. Carpeta maestra mínima</h2><div class='grid-2'><ul><li>Personería, RUT/NIT, certificados y representantes.</li><li>Estados financieros, cuentas, referencias y política anticorrupción.</li><li>Experiencia y contratos/certificaciones verificables.</li><li>Currículos del equipo y estructura de gobernanza.</li><li>Diagnóstico con fuente, población, territorio y línea base.</li></ul><ul><li>Teoría de cambio, resultados, indicadores y medios de verificación.</li><li>Presupuesto por rubros, contrapartida y sostenibilidad.</li><li>Cronograma, riesgos, compras y plan de ejecución.</li><li>Accesibilidad, participación de mayores, protección de datos y salvaguardas.</li><li>Para SGR: MGA/BPIN/PIIP; para SECOP: RUP/pliegos/garantías.</li></ul></div><h2>3. Calendario sugerido</h2><table><thead><tr><th>Cuándo</th><th>Acción</th><th>Decisión de salida</th></tr></thead><tbody><tr><td>19–23 nov 2026</td><td>Verificar 27 avisos SECOP; inscribir CCB; revisar finalistas CAF el 23.</td><td>Descartar procesos vencidos y asignar responsables.</td><tr><td>Antes del 30 nov</td><td>Evaluar Pollination en inglés; revisar resultados de convocatorias MinCiencias.</td><td>Aplicar solo si cumple voluntariado y presupuestos.</td><tr><td>Antes del 6 dic</td><td>Registrar prórroga D-Prize y preparar concepto de dos páginas.</td><td>Presentar solo con intervención probada y organización nueva.</td><tr><td>Diciembre 2026</td><td>DRK screener/deck; seguir Pitch Day CAF el 9; resultados CTeI.</td><td>Go/no-go DRK según piloto, escala y gobierno.</td><tr><td>Ene–feb 2027</td><td>Revisar Concertación Cultural y reapertura Pollination.</td><td>Ajustar a bases finales, sin comprometer gastos anticipados.</td><tr><td>Permanente</td><td>Municipio/SGR, CCB, SECOP, BID y alianzas técnicas.</td><td>Pipeline actualizado semanalmente.</td></tbody></table></section>""")
    chapters.append("""<section><h2>Matriz de presencia física</h2><table><thead><tr><th>Escenario</th><th>Postulación</th><th>Presencia exigida o esperada</th></tr></thead><tbody><tr><td>CCB Programa / Clúster</td><td>Formulario digital</td><td>No obligación general visible; eventos/retos según convocatoria.</td><tr><td>SDIS y operación social</td><td>SECOP II cuando se indique</td><td>Ejecución de servicios en Bogotá y puntos definidos.</td><tr><td>Estampilla Cundinamarca</td><td>Gestión municipal, no formulario privado</td><td>Articulación municipal y ejecución territorial.</td><tr><td>Idartes Danza Mayor</td><td>CultuRed</td><td>Residencia Bogotá de integrantes y audición presencial.</td><tr><td>PDAC</td><td>CultuRed</td><td>ESAL con domicilio/sede y ejecución en Bogotá.</td><tr><td>SGR / OCAD Paz</td><td>SUIFP / PIIP / SIIAT</td><td>Entidad habilitada, socialización cuando aplique e inversión territorial.</td><tr><td>MinCiencias 54 / 55 / 56</td><td>PIIP y formatos</td><td>Intervención multidepartamental/multirregional o en territorios afectados.</td><tr><td>SECOP II</td><td>Digital</td><td>Lugar, visitas y ejecución según expediente.</td><tr><td>D-Prize / DRK / Pollination / GlobalGiving</td><td>Digital</td><td>No punto físico para aplicar; intervención real en comunidad.</td></tbody></table><h2>Controles antes de postular</h2><ol><li><strong>Identidad:</strong> persona, grupo, empresa, ESAL, academia, comunidad étnica o entidad pública.</li><li><strong>Geografía:</strong> registro, operación, sede, residencia y ejecución pueden ser requisitos distintos.</li><li><strong>Madurez:</strong> idea, MVP, piloto, tracción, Seed o escala.</li><li><strong>Tema:</strong> personas mayores como población central, no accesoria.</li><li><strong>Instrumento:</strong> dinero, inversión, kit, servicio, contrato o red.</li><li><strong>Vigencia:</strong> adendas, cierre con hora/zona y resultados antes de gastar.</li><li><strong>Costo total:</strong> contrapartida, garantías, impuestos, tarifas, auditoría, viajes y operación posterior.</li></ol><div class='callout'><strong>Regla:</strong> si una fuente no tiene canal actual, requisitos verificables y encaje explícito, pasa a vigilancia; no al presupuesto de ingresos.</div></section>""")
    unique={}
